import {readFileSync,writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {sourceHash,validateInventory} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/';
const read=(p:string)=>JSON.parse(readFileSync(p,'utf8'));
const assert=(ok:unknown,message:string)=>{if(!ok)throw Error(message);};
const catalog=read(root+'executable-catalog.json');
const manifest=read(root+'quality-classifications.json');
const ledger=read(root+'work-items.json');
const probe=read(root+'evidence/B04-applicability-probe.json');
const boundary=read(root+'evidence/B04-counter-boundary-probe.json');
const prior=JSON.parse(execFileSync('git',['show','HEAD:'+root+'quality-classifications.json'],{encoding:'utf8'}));
assert(validateInventory(catalog,manifest).length===0,'Invalid structural inventory');
assert(probe.rows.length===446&&manifest.files.length===446,'Wrong file count');
for(const old of prior.files){const current={...manifest.files.find((x:any)=>x.path===old.path)};delete current.metricApplicability;assert(JSON.stringify(old)===JSON.stringify(current),'Existing risk/applicability changed '+old.path);}
for(const file of catalog.files){
 assert(sourceHash(readFileSync(file.path,'utf8'))===file.sourceHash,'Stale source '+file.path);
 const entry=manifest.files.find((x:any)=>x.path===file.path);
 const row=probe.rows.find((x:any)=>x.path===file.path);
 assert(row?.sourceHash===file.sourceHash&&entry.metricApplicability.sourceHash===file.sourceHash,'Stale metric proposal '+file.path);
 assert(entry.metricApplicability.status==='proposed - independent review pending','Premature approval');
 assert(Object.keys(entry.metricApplicability.metrics).sort().join()==='branches,functions,lines,statements','Missing metrics '+file.path);
 for(const [metric,value] of Object.entries(entry.metricApplicability.metrics) as any){
  assert(value.observedCounterTotal===(row.metrics?.[metric].total??null),'Wrong total '+file.path);
  if(row.metrics)assert(row.metrics[metric].covered===0,'Probe incorrectly claims runtime coverage');
 }
}
for(const input of [...catalog.packages,...read(root+'package-boundary-map.json').sourceInputs,...probe.sourceInputs])assert(sourceHash(readFileSync(input.path,'utf8'))===input.sourceHash,'Stale input '+input.path);
assert(probe.instrumenterSourceHash===sourceHash(readFileSync('scripts/run-istanbul-bun-coverage.ts','utf8')),'Stale instrumenter');
assert(boundary.instrumenterSourceHash===probe.instrumenterSourceHash,'Different counter probe instrumenter');
const byId=new Map<string,any>(ledger.items.map((x:any)=>[x.id,x]));
assert(byId.size===218&&ledger.items.length===218,'Wrong ledger size');
const visited=new Set<string>();
function visit(id:string,stack=new Set<string>()){
 assert(!stack.has(id),'Dependency cycle '+id);if(visited.has(id))return;assert(byId.has(id),'Missing dependency '+id);
 for(const dep of byId.get(id).depends_on)visit(dep,new Set([...stack,id]));visited.add(id);
}
for(const id of byId.keys())visit(id);
function reaches(id:string,target:string):boolean{return id===target||byId.get(id).depends_on.some((dep:string)=>reaches(dep,target));}
for(const id of ['B05.1','B05.2','B05.3'])for(const gate of ['B05','B07','B09','R02'])assert(reaches(gate,id),'Counter repair bypass '+id);
for(const item of ledger.items.filter((x:any)=>x.id.startsWith('B11.')&&x.id!=='B11.3'))assert(reaches('B09',item.id),'Cleanup bypass '+item.id);
assert(ledger.items.filter((x:any)=>x.status==='active').map((x:any)=>x.id).join()==='B04','Active item mismatch');
assert(byId.get('B05').status==='pending','Premature instrumentation acceptance');
const record={status:'PASS',sourceBindings:446,packageBindings:2,metricEntries:1784,tiersUnchanged:true,applicabilityApproval:'pending',ledgerItems:218,acyclic:true,repairTasksBlockBaseline:true,probeCommandExit:0,counterProbeCommandExit:0,limits:'Structural/source consistency and observed synthetic diagnostics; no independent review or full quality acceptance.',verificationSource:readFileSync('.git/b04-validate-applicability.ts','utf8')};
writeFileSync(root+'evidence/B04-applicability-validation.json',JSON.stringify(record,null,2)+'\n');console.log(JSON.stringify({...record,verificationSource:'retained in evidence'}));
